        <svg class="icon"><use xlink:href="#icon-refresh"></use></svg>
        <span class="text">show more</span>
    </a>
</div>

<div style="float:right;">
    {{> components/common/paginator pagination.product_results reload=true total=category.total_products}}
</div>
<script>
	var jdgmReloadFlag = 0;
	setInterval(function() {
		if(jQuery && jdgmCacheServer && "undefined" != typeof jdgmSettings) {
			var jdgm_preview_badge = jQuery("div.jdgm-preview-badge").length;
			var jdgm_done_setup = jQuery("div.jdgm--done-setup").length;
			if(jdgmReloadFlag == 0 && jdgm_preview_badge != 0 && jdgm_preview_badge != jdgm_done_setup) {
				jdgmReloadFlag = 1;
				jdgmCacheServer.reloadPreviewBadges();
			}
			else {
				if(jdgm_done_setup != 0 && jdgm_preview_badge != jdgm_done_setup && jdgmReloadFlag == 1) {
					jdgmReloadFlag++;
					jdgmCacheServer.reloadPreviewBadges();
				}
				else if(jdgm_done_setup != 0 && jdgm_preview_badge == jdgm_done_setup && jdgmReloadFlag > 1) {
					jdgmReloadFlag = 1;
				}
			}
		}
	}, 3500);
</script>

